/**
 * Deterministic seed for SUPER Z SHOP.
 *
 * Reads data/catalogue/*.json (generated by scripts/build_catalogue.py) and
 * populates the SQLite database. Safe to re-run: `npm run db:reset` wipes first.
 *
 * Run: npm run db:seed
 */
import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import { DatabaseSync } from "node:sqlite";

const ROOT = process.cwd();
const DB_PATH = path.resolve(ROOT, process.env.DATABASE_PATH || "db/super-z-shop.db");
const readJson = (p) => JSON.parse(fs.readFileSync(path.join(ROOT, p), "utf8"));

const products = readJson("data/catalogue/products.json");
const categories = readJson("data/catalogue/categories.json");
const locations = readJson("data/catalogue/locations.json");

fs.mkdirSync(path.dirname(DB_PATH), { recursive: true });
const db = new DatabaseSync(DB_PATH);
db.exec("PRAGMA foreign_keys = ON");

// ---- migrations -----------------------------------------------------------
db.exec("CREATE TABLE IF NOT EXISTS _migrations (name TEXT PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT (datetime('now')))");
const migDir = path.join(ROOT, "db/migrations");
for (const file of fs.readdirSync(migDir).filter((f) => f.endsWith(".sql")).sort()) {
  if (db.prepare("SELECT 1 FROM _migrations WHERE name = ?").get(file)) continue;
  db.exec(fs.readFileSync(path.join(migDir, file), "utf8"));
  db.prepare("INSERT INTO _migrations (name) VALUES (?)").run(file);
  console.log(`  migration applied: ${file}`);
}

// ---- clean slate ----------------------------------------------------------
const tables = [
  "order_items", "orders", "cart_items", "carts", "wishlist", "inventory_movements",
  "product_images", "product_variants", "products", "subcategories", "categories",
  "addresses", "customers", "coupons", "banners", "admin_users", "store_settings",
  "newsletter_subscribers", "contact_messages",
];
for (const t of tables) db.exec(`DELETE FROM ${t}`);
db.exec("DELETE FROM sqlite_sequence");

// ---- helpers --------------------------------------------------------------
function hashPassword(password, salt = crypto.randomBytes(16).toString("hex")) {
  const hash = crypto.scryptSync(password, salt, 64).toString("hex");
  return `scrypt:${salt}:${hash}`;
}

const productIdToRowId = new Map();
let variantCount = 0;

const insertCategory = db.prepare(
  `INSERT INTO categories (slug, name, name_bn, blurb, icon, sort_order) VALUES (?, ?, ?, ?, ?, ?)`,
);
const insertSub = db.prepare(`INSERT INTO subcategories (category_id, slug, name) VALUES (?, ?, ?)`);
const insertProduct = db.prepare(`
  INSERT INTO products
    (sku, slug, name, name_bn, category_id, subcategory, short_description, description,
     specs_json, wholesale_cost, retail_price, sale_price, price_status, moq, tags_json, flags_json, warranty)
  VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`);
const insertVariant = db.prepare(`
  INSERT INTO product_variants (product_id, variant_sku, size, color, price_delta, stock)
  VALUES (?, ?, ?, ?, 0, ?)`);
const insertImage = db.prepare(`
  INSERT INTO product_images (product_id, url, alt, kind, sort_order) VALUES (?, ?, ?, ?, ?)`);
const insertMove = db.prepare(`
  INSERT INTO inventory_movements (product_id, variant_id, change_qty, reason, reference, note)
  VALUES (?, ?, ?, ?, ?, ?)`);

const catIdBySlug = new Map();
db.exec("BEGIN");
try {
  for (const c of categories) {
    const res = insertCategory.run(c.slug, c.name, c.nameBn, c.blurb, c.icon, c.sortOrder);
    const catId = Number(res.lastInsertRowid);
    catIdBySlug.set(c.slug, catId);
    for (const s of c.subcategories) insertSub.run(catId, s.slug, s.name);
  }

  for (const p of products) {
    const catId = catIdBySlug.get(p.categorySlug);
    const description = [
      p.shortDescription,
      `${p.name} is part of the ${categories.find((c) => c.slug === p.categorySlug)?.name} range at SUPER Z SHOP.`,
      `Suggested minimum order quantity from sourcing: ${p.moq} pcs.`,
      `Replacement policy: ${p.warranty}.`,
    ].join("\n\n");
    const specs = {
      Material: p.tags.includes("cotton") ? "Cotton" : p.tags.includes("leather") ? "Leather / PU" : "Mixed",
      Colour: p.colors.join(", "),
      Sizes: p.sizes.length ? p.sizes.join(", ") : "One size",
      Warranty: p.warranty,
      MOQ: `${p.moq} pcs`,
      "Sourcing status": "Wholesale cost is an indicative Dhaka market estimate — verify against a supplier invoice",
    };
    const res = insertProduct.run(
      p.sku, p.slug, p.name, p.nameBn, catId, p.subcategory, p.shortDescription, description,
      JSON.stringify(specs), p.wholesaleCost, p.retailPrice, p.salePrice, p.priceStatus, p.moq,
      JSON.stringify(p.tags), JSON.stringify(p.flags), p.warranty,
    );
    const pid = Number(res.lastInsertRowid);
    productIdToRowId.set(p.id, pid);

    insertImage.run(pid, `/products/${p.sku}.jpg`, `${p.name} — studio product photograph`, "photo", 0);

    const sizes = p.sizes.length ? p.sizes : ["One Size"];
    for (const colour of p.colors) {
      for (const size of sizes) {
        const variantSku = `${p.sku}-${colour.slice(0, 3).toUpperCase()}-${size.replace(/\s+/g, "").toUpperCase()}`;
        // Deterministic stock: 0–34, with a handful of low-stock and sold-out rows
        const h = (pid * 7 + variantCount * 13) % 36;
        const stock = h < 3 ? 0 : h < 8 ? h : 8 + (h % 22);
        const vres = insertVariant.run(pid, variantSku, size, colour, stock);
        const vid = Number(vres.lastInsertRowid);
        insertMove.run(pid, vid, stock, "seed", "SEED-2026", "Opening stock for demo");
        variantCount += 1;
      }
    }
  }
  db.exec("COMMIT");
} catch (e) {
  db.exec("ROLLBACK");
  throw e;
}
console.log(`  categories: ${categories.length}, products: ${products.length}, variants: ${variantCount}`);

// ---- store settings, coupons, banners, admin -------------------------------
const settings = {
  store_name: "SUPER Z SHOP",
  tagline: "Premium Everyday Essentials",
  currency: "BDT",
  delivery_fee_dhaka: "70",
  delivery_fee_outside: "130",
  free_delivery_threshold: "2500",
  support_phone: "+880 1700 000000",
  support_email: "hello@superzshop.bd",
  demo_mode: "true",
  price_disclaimer:
    "All prices are demo data. Wholesale and retail prices are unverified market estimates and must be confirmed with a supplier before selling.",
};
const insertSetting = db.prepare("INSERT INTO store_settings (key, value) VALUES (?, ?)");
for (const [k, v] of Object.entries(settings)) insertSetting.run(k, v);

const coupons = [
  ["WELCOME10", "10% off first order (max ৳300)", "percent", 10, 1000, 300, null],
  ["EID500", "৳500 off orders over ৳5,000", "fixed", 500, 5000, null, 200],
  ["FREESHIP", "Free delivery inside Dhaka", "freeship", 0, 1500, null, null],
  ["SUPERZ15", "15% off selected lifestyle items (max ৳500)", "percent", 15, 2000, 500, 100],
];
const insertCoupon = db.prepare(
  `INSERT INTO coupons (code, description, type, value, min_subtotal, max_discount, usage_limit) VALUES (?, ?, ?, ?, ?, ?, ?)`,
);
for (const c of coupons) insertCoupon.run(...c);

const banners = [
  ["hero", "Premium everyday essentials, sourced in Dhaka", "Clothing, jewellery, watches and small tech — priced for Bangladesh, delivered nationwide.", "Shop the collection", "/shop", "ink", 0],
  ["hero", "Eid edit: panjabi, saree & gifting", "Curated festive pieces with 7-day replacement support.", "Explore festive", "/category/seasonal-collections", "sand", 1],
  ["promo", "Free delivery over ৳2,500", "Cash on delivery available across all 64 districts.", "See delivery policy", "/pages/shipping-delivery-policy", "olive", 2],
  ["strip", "Unverified demo catalogue", "225 products with estimated prices — supplier invoices pending.", "Read the note", "/pages/about-us", "ink", 3],
];
const insertBanner = db.prepare(
  `INSERT INTO banners (placement, title, subtitle, cta_label, cta_href, theme, sort_order) VALUES (?, ?, ?, ?, ?, ?, ?)`,
);
for (const b of banners) insertBanner.run(...b);

const adminEmail = process.env.ADMIN_EMAIL || "admin@superzshop.bd";
const adminPassword = process.env.ADMIN_PASSWORD || "SuperZ@2026";
db.prepare(`INSERT INTO admin_users (email, name, password_hash, role) VALUES (?, ?, ?, ?)`).run(
  adminEmail,
  "Store Admin",
  hashPassword(adminPassword),
  "owner",
);

// ---- demo customers + orders ---------------------------------------------
const customers = [
  ["Ayesha Rahman", "ayesha.rahman@example.com", "01711000001", "House 24, Road 9, Dhanmondi", "Dhanmondi", "Dhaka", "1209"],
  ["Tanvir Hossain", "tanvir.hossain@example.com", "01822000002", "Flat 5B, Navana Tower, Gulshan 1", "Gulshan", "Dhaka", "1212"],
  ["Nusrat Jahan", "nusrat.jahan@example.com", "01933000003", "112 CDA Avenue, Nasirabad", "Nasirabad", "Chattogram", "4000"],
  ["Rifat Chowdhury", "rifat.chowdhury@example.com", "01644000004", "Mirpur 10, Block C", "Mirpur", "Dhaka", "1216"],
  ["Sadia Islam", "sadia.islam@example.com", "01555000005", "Zindabazar Point, Level 2", "Zindabazar", "Sylhet", "3100"],
  ["Mahmud Karim", "mahmud.karim@example.com", "01766000006", "Sector 7, Road 12, Uttara", "Uttara", "Dhaka", "1230"],
  ["Farhana Akter", "farhana.akter@example.com", "01877000007", "Sonadanga R/A, Block B", "Sonadanga", "Khulna", "9100"],
  ["Imran Sheikh", "imran.sheikh@example.com", "01988000008", "Chashara, Narayanganj Sadar", "Chashara", "Narayanganj", "1400"],
];
const insertCustomer = db.prepare(`INSERT INTO customers (name, email, phone) VALUES (?, ?, ?)`);
const insertAddress = db.prepare(
  `INSERT INTO addresses (customer_id, label, address_line, area, district, postcode, phone, is_default) VALUES (?, 'Home', ?, ?, ?, ?, ?, 1)`,
);
const customerIds = [];
for (const [name, email, phone, line, area, district, post] of customers) {
  const r = insertCustomer.run(name, email, phone);
  const cid = Number(r.lastInsertRowid);
  customerIds.push(cid);
  insertAddress.run(cid, line, area, district, post, phone);
}

const variants = db.prepare(`
  SELECT v.id, v.product_id, v.stock, v.size, v.color, v.variant_sku,
         p.name, p.sku, p.retail_price, p.sale_price, p.wholesale_cost
  FROM product_variants v JOIN products p ON p.id = v.product_id
  WHERE v.stock > 0
`).all();

const insertOrder = db.prepare(`
  INSERT INTO orders (order_number, customer_id, status, payment_method, payment_status, subtotal, discount,
    delivery_fee, total, coupon_code, ship_name, ship_phone, ship_email, ship_address, ship_area,
    ship_district, notes, courier, tracking_code, created_at, updated_at)
  VALUES (?, ?, ?, 'cod', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`);
const insertOrderItem = db.prepare(`
  INSERT INTO order_items (order_id, product_id, variant_id, name, sku, variant_label, unit_price, qty, line_total, unit_cost)
  VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`);

const statuses = [
  "delivered", "delivered", "delivered", "shipped", "packed",
  "confirmed", "pending", "delivered", "cancelled", "delivered",
  "delivered", "shipped", "delivered", "returned", "delivered",
  "delivered", "confirmed", "delivered",
];
const courierByStatus = {
  shipped: "Pathao Courier", packed: "Not assigned", confirmed: "Not assigned",
  pending: "Not assigned", delivered: "Steadfast", cancelled: "Not assigned", returned: "RedX",
};

let seedIndex = 0;
for (let i = 0; i < statuses.length; i += 1) {
  const custIdx = i % customers.length;
  const [name, , phone, line, area, district] = customers[custIdx];
  const email = customers[custIdx][1];
  const daysAgo = 46 - i * 2;
  const created = new Date(Date.now() - daysAgo * 86400000).toISOString().replace("T", " ").slice(0, 19);
  const itemCount = 1 + (i % 3);
  const picks = [];
  for (let k = 0; k < itemCount; k += 1) {
    const v = variants[(seedIndex * 17 + k * 23 + i * 5) % variants.length];
    const qty = 1 + ((i + k) % 2);
    const price = v.sale_price ?? v.retail_price;
    picks.push({ v, qty, price });
    seedIndex += 1;
  }
  const subtotal = picks.reduce((s, x) => s + x.price * x.qty, 0);
  const deliveryFee = district === "Dhaka" ? 70 : 130;
  const discount = i === 3 ? 200 : 0;
  const total = subtotal - discount + deliveryFee;
  const status = statuses[i];
  const orderNumber = `SZS-${String(2026001 + i)}`;
  const tracking = status === "shipped" || status === "delivered" ? `TRK${9000 + i}${i * 7}` : "";
  const r = insertOrder.run(
    orderNumber, customerIds[custIdx], status, status === "delivered" ? "paid" : status === "cancelled" ? "void" : "unpaid",
    subtotal, discount, deliveryFee, total, i === 3 ? "WELCOME10" : null,
    name, phone, email, line, area, district, "", courierByStatus[status] ?? "Not assigned", tracking, created, created,
  );
  const oid = Number(r.lastInsertRowid);
  for (const { v, qty, price } of picks) {
    insertOrderItem.run(oid, v.product_id, v.id, v.name, v.sku, `${v.size} / ${v.color}`, price, qty, price * qty, v.wholesale_cost);
    db.prepare(`UPDATE product_variants SET stock = MAX(stock - ?, 0) WHERE id = ?`).run(qty, v.id);
    insertMove.run(v.product_id, v.id, -qty, "order", orderNumber, "Seeded demo order");
  }
}
console.log(`  customers: ${customers.length}, orders: ${statuses.length}, coupons: ${coupons.length}`);

const check = db.prepare("SELECT COUNT(*) AS n FROM products").get();
console.log(`\nSeed complete. Products in DB: ${check.n}. Database: ${DB_PATH}`);
console.log(`Demo admin login: ${adminEmail} / ${adminPassword}`);

// The connection runs in WAL mode, so the last committed pages can still live in
// the -wal sidecar. Checkpoint them into the main file and switch back to
// journal_mode=DELETE before closing: a deployment only ever copies the .db
// file into the build bundle, and it must be complete on its own.
try {
  db.exec("PRAGMA wal_checkpoint(TRUNCATE)");
  db.exec("PRAGMA journal_mode = DELETE");
} catch {
  // Another process (a running dev server) has the file open, so the mode
  // switch is refused. Harmless locally: the seed data is committed either way.
  console.warn("  note: left the database in WAL mode (file in use by another process)");
}
db.close();
